// The size records (Shroomish / Barboach): Sapphire compares the shown Pokemon's size (a hash of personality and IVs, scaled by the Pokedex height) with the record in VAR_SHROOMISH/BARBOACH_SIZE_RECORD. Black 2's scripts cannot read personality or IVs (PokePartyGetParam is a short whitelist), so the size of a shown Pokemon of the right species is drawn at random (10-26 inches); the record starts at Marco's 16 inches, as Sapphire's 0x8100, and the Elixir, the lines and the record signs work as Sapphire's.
#include "scenes/ch10_lib.inc"
#define T_PleaseShowMeBigShroomish 1
#define T_GoshMightBeBigger 2
#define T_BagCrammedFull1 3
#define T_SeenBiggerShroomish 4
#define T_ThatsNotShroomish 5
#define T_DontHaveBigShroomish 6
#define T_BiggestShroomish 7
#define T_BiggestShroomishMarco 8
#define T_PleaseShowMeBigBarboach 9
#define T_WowMightBeBigger 10
#define T_SeenBiggerBarboach 11
#define T_ThatsNotBarboach 12
#define T_DontHaveBigBarboach 13
#define T_BiggestBarboach 14
#define T_BiggestBarboachMarco 15
#define T_BagIsFull 16
// the faux size of the shown Pokémon: 10-26 inches into H8_SIZE
#define H8_SIZE C10_D

    .macro h8_brother species, tPlease, tGosh, tBagFull, tSeen, tNot, tDont, recVar, recFlag
    c10_talk
    h_msgbox \tPlease                   // Do you know the Pokémon ...? ... P-p-please, show me!
    MsgWinCloseAll
    CallPokeSelect 0, C10_A, C10_B, 0   // special SelectMonForNPCTrade: C10_A 1 = chosen, C10_B = party slot
    WorkCmpConst C10_A, 0
    VMJumpIf CMP_EQ, .Lh8dont\@         // VAR_RESULT 255: cancelled
    PokePartyIsEgg C10_A, C10_B         // special Compare...Size: an Egg or another species = 1
    WorkCmpConst C10_A, 1
    VMJumpIf CMP_EQ, .Lh8not\@
    PokePartyGetSpecies C10_A, C10_B
    WorkCmpConst C10_A, \species
    VMJumpIf CMP_NE, .Lh8not\@
    h_random H8_SIZE, 17                // the size (see the note above)
    h_addvar H8_SIZE, 10
    WordSetNumber 2, H8_SIZE, 2
    WorkSet C10_A, \recVar              // the record (0 = Marco's 16 inches)
    WorkCmpConst C10_A, 0
    VMJumpIf CMP_NE, .Lh8have\@
    WorkSetConst C10_A, 16
.Lh8have\@:
    WorkCmpWork H8_SIZE, C10_A
    VMJumpIf CMP_LE, .Lh8small\@        // newSize <= oldSize: 2
    WorkSet \recVar, H8_SIZE            // a new record: 3
    FlagSet \recFlag
    h_msgbox \tGosh                     // <size> inches! Oh, my gosh, this is a big one! ... This is my thanks!
    h_closemessage
    h_giveitem ITEM_ELIXIR
    h_goto_if_eq HLIB_RESULT, 0, .Lh8bag\@
    h_release
.Lh8bag\@:
    h_msgbox \tBagFull                  // Hunh? Your Bag is crammed full.
    h_release
.Lh8small\@:
    h_msgbox \tSeen                     // <size> inches, is it? Hmm... I've seen a bigger ... than this one.
    h_release
.Lh8not\@:
    h_msgbox \tNot                      // ... But it's not a ...!
    h_release
.Lh8dont\@:
    h_msgbox \tDont                     // You don't have a big ...? That's too bad...
    h_release
    .endm

    .macro h8_record recVar, recFlag, tPlayer, tMarco
    c10_lock
    WorkSet C10_A, \recVar
    WorkCmpConst C10_A, 0
    VMJumpIf CMP_NE, .Lh8r1\@
    WorkSetConst C10_A, 16
.Lh8r1\@:
    WordSetNumber 3, C10_A, 2
    FlagGet \recFlag, C10_B
    WorkCmpConst C10_B, 1
    VMJumpIf CMP_EQ, .Lh8r2\@
    h_msgbox_info \tMarco               // The biggest ... in history! Marco's <size>-inch giant! ...
    h_closemessage
    h_release
.Lh8r2\@:
    WordSetPlayerName 2
    h_msgbox_info \tPlayer              // The biggest ... in history! <player>'s <size>-inch giant! ...
    h_closemessage
    h_release
    .endm

